// Builds one WhatsApp template message per order event from the YAHIVO store.
// Template (create it in WhatsApp Manager, category Utility, language English):
//   name: yahivo_order_update   body: Hi {{1}}, an update on your YAHIVO order {{2}}: {{3}}
const STATUS_TEXT = {
  preparing: () => 'we are preparing it.',
  packed: () => 'it is packed and waiting for the courier.',
  handed_to_courier: (o) => `it is with ${o.courierName ?? 'the courier'}.${o.trackingUrl || o.trackingNumber ? ` Tracking: ${o.trackingUrl ?? o.trackingNumber}` : ''}`,
  delivered: () => 'it has been delivered. Thank you for shopping with YAHIVO.',
  cancelled: () => 'it has been cancelled.',
};
const out = [];
for (const item of $input.all()) {
  const { event, order: o } = item.json.body ?? {};
  if (!o?.customer?.phone) continue;
  let text = null;
  if (event === 'order.created') text = `we received it. Total ${o.currency} ${Number(o.total).toFixed(2)} (${o.paymentMethod}). Details: ${o.orderUrl}`;
  else if (event === 'order.status_changed' && STATUS_TEXT[o.status]) text = STATUS_TEXT[o.status](o);
  else if (event === 'order.return_requested') text = 'we received your return request. Our team will contact you to arrange it.';
  if (!text) continue;
  // WhatsApp wants the number in international format without + or spaces. Local UAE numbers (05x) get 971.
  let to = String(o.customer.phone).replace(/\D/g, '');
  if (to.startsWith('00')) to = to.slice(2);
  else if (to.startsWith('0')) to = `971${to.slice(1)}`;
  const firstName = String(o.customer.name ?? '').split(' ')[0] || 'there';
  out.push({ json: { to, firstName, number: o.number, text: text.replace(/\s+/g, ' ').slice(0, 900) } });
}
return out;
